def name_operands(region,function_address,operation):
    if region=='Action' and function_address in FUNCTIONS:
        operation=operation.replace('(#CF03)','(@ActionClipPointWritersState.CornerBlock)').replace('(#9BA3)','(@ActionClipIntersectionsState.OutputSize)')
        operation=operation.replace('(#CF1B)','(@ActionClipProductsState.SecondPoint+FRenderProjectedPoint.Second)').replace('(#CF1D)','(@ActionClipProductsState.SecondPoint+FRenderProjectedPoint.First)')
        operation=operation.replace('LD H, #90','LD H, @ActionClipIntersectionConst.OutputPage')
        pair=DETAILS[function_address][1]
        if pair is not None:
            operation=operation.replace('LD DE, #'+format(pair,'04X'),'LD DE, @ActionClipCornerConst.'+DETAILS[function_address][0].replace('Append','').replace('ClipCorner',''))
    for point in ('FirstPoint','SecondPoint'):
        operation=operation.replace('@ActionClipProductsState.'+point+'+FRenderProjectedPoint.','@ActionClipPoints.'+point+'.')
    return operation
